import bisect

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [-1] * (self.n + 2)  # 1-based indexing

    def update(self, idx, value):
        while idx <= self.n:
            if value > self.tree[idx]:
                self.tree[idx] = value
            else:
                break  # No need to proceed if current value is not larger
            idx += idx & -idx

    def query(self, idx):
        res = -1
        while idx > 0:
            if self.tree[idx] > res:
                res = self.tree[idx]
            idx -= idx & -idx
        return res

n = int(input())
