                        if x == 0:
                            damage = sum_d
                        elif x == 1:
                            damage = best_s2[0] * 2 + best_s2[1]
                        elif x == 2:
                            damage = best_s2[0] + best_s2[1] * 2
                        else:
                            damage = -10**18
                    elif s == 3:
                        if not best_s3:
                            continue
                        sum_d = best_s3[0] + best_s3[1] + best_s3[2]
                        if x == 0:
                            damage = sum_d
                        elif x >= 1:
                            damage = best_s3[0] * 2 + (best_s3[1] + best_s3[2])
                        else:
                            damage = -10**18
                    else:
                        damage = -10**18
                    new_m = (m_prev + s) % 10
                    total = dp_prev[m_prev] + damage
                    if total > dp_new[new_m]:
                        dp_new[new_m] = total

