def generate_lucky_numbers(n):
    lucky = []
    max_digits = len(str(n)) if n > 0 else 0
    for length in range(1, 10):
        for digits in product('47', repeat=length):
            num_str = ''.join(digits)
            if len(num_str) > max_digits:
                continue
            num = int(num_str)
            if num <= n:
                lucky.append(num)
