def generate_kth_permutation(S, k):
    m = len(S)
    perm = []
    remaining = list(S)
    current_k = k - 1  # Convert to 0-based index
    for i in range(m):
        factorial = 1
        for j in range(1, m - i):
            factorial *= j
        index = current_k // factorial
        perm.append(remaining.pop(index))
        current_k %= factorial
    return perm

def main():
