            area = len(blob)
            if area > max_area:
                max_area = area
                perimeter = 0
                for (x, y) in blob:
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if nx < 0 or nx >= n or ny < 0 or ny >= n:
