        best_b = []
        if len(c1_sorted) >= 1 and len(c2_sorted) >= 1:
            best_b = [c1_sorted[0], c2_sorted[0]]
        if best_a and (not best_b or sum(best_a) >= sum(best_b)):
            best_s2 = best_a.copy()
        else:
            best_s2 = best_b.copy() if best_b else []
        if len(best_s2) >= 2:
