import bisect

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [-1] * (self.n + 2)  # 1-based indexing

    def update(self, idx, value):
        while idx <= self.n:
            if value > self.tree[idx]:
                self.tree[idx] = value
            else:
                break  # No need to proceed if current value is not larger
            idx += idx & -idx

    def query(self, idx):
        res = -1
        while idx > 0:
            if self.tree[idx] > res:
                res = self.tree[idx]
            idx -= idx & -idx
        return res

n = int(input())
a = list(map(int, input().split()))
sorted_unique = sorted(set(a))
m = len(sorted_unique)

fenwick = FenwickTree(m)
ans = [-1] * n

for i in range(n-1, -1, -1):
    x = a[i]
    k = bisect.bisect_left(sorted_unique, x)
    if k == 0:
        ans[i] = -1
    else:
        max_rank = k - 1
        max_j = fenwick.query(max_rank + 1)
        if max_j != -1:
            ans[i] = max_j - i - 1
        else:
            ans[i] = -1
    compressed_rank = bisect.bisect_left(sorted_unique, x)
    fenwick.update(compressed_rank + 1, i)

