import sys

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    if n == 0:
        print()
        return

    # Compute left array
    left = [-1] * n
    stack = []
    for i in range(n):
        while stack and a[stack[-1]] >= a[i]:
            stack.pop()
        if stack:
            left[i] = stack[-1]
        else:
            left[i] = -1
        stack.append(i)

    # Compute right array
    right = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and a[stack[-1]] >= a[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1]
        else:
            right[i] = n
        stack.append(i)

    L = [right[i] - left[i] - 1 for i in range(n)]

    # Segment Tree implementation
    class SegmentTree:
        def __init__(self, size):
            self.n = size
            self.size_tree = 1
            while self.size_tree < self.n:
                self.size_tree <<= 1
            self.tree = [0] * (2 * self.size_tree)
            self.lazy = [0] * (2 * self.size_tree)

        def push(self, node, l, r):
            if self.lazy[node] != 0:
                self.tree[node] = max(self.tree[node], self.lazy[node])
                if l != r:
                    self.lazy[2 * node] = max(self.lazy[2 * node], self.lazy[node])
                    self.lazy[2 * node + 1] = max(self.lazy[2 * node + 1], self.lazy[node])
                self.lazy[node] = 0

        def update_range(self, a, b, val):
            def update(node, l, r):
                self.push(node, l, r)
                if a > r or b < l:
                    return
                if a <= l and r <= b:
                    self.lazy[node] = max(self.lazy[node], val)
                    self.push(node, l, r)
                    return
                mid = (l + r) // 2
                update(2 * node, l, mid)
                update(2 * node + 1, mid + 1, r)
                self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])
            update(1, 0, self.size_tree - 1)

        def query_point(self, idx):
            res = 0
            def query(node, l, r):
                self.push(node, l, r)
                if l == r:
                    return self.tree[node]
                mid = (l + r) // 2
                if idx <= mid:
                    return query(2 * node, l, mid)
                else:
                    return query(2 * node + 1, mid + 1, r)
            return query(1, 0, self.size_tree - 1)

    st = SegmentTree(n)
    for i in range(n):
        current_L = L[i]
        if current_L > 0:
            st.update_range(1, current_L, a[i])

    ans = [0] * (n + 1)
    for k in range(1, n + 1):
        ans[k] = st.query_point(k)

    print(' '.join(map(str, ans[1:])))

if __name__ == "__main__":
    main()
