                if basis[i] == 0:
                    basis[i] = current
                    break
                else:
                    current ^= basis[i]

    max_xor = 0
    for i in reversed(range(60)):
        if basis[i] != 0:
            if (max_xor ^ basis[i]) > max_xor:
                max_xor ^= basis[i]

    if max_xor == 0:
