            queue = deque([(i, j)])
            visited[i][j] = True
            blob = []
            while queue:
                x, y = queue.popleft()
                blob.append((x, y))
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == '#' and not visited[nx][ny]:
                        visited[nx][ny] = True
                        queue.append((nx, ny))
            area = len(blob)
            if area > max_area:
                max_area = area
