    for num in masked:
        current = num
        for i in reversed(range(60)):
            if current & (1 << i):
                if basis[i] == 0:
                    basis[i] = current
                    break
                else:
                    current ^= basis[i]

    max_xor = 0
    for i in reversed(range(60)):
        if basis[i] != 0:
            if (max_xor ^ basis[i]) > max_xor:
                max_xor ^= basis[i]

    if max_xor == 0:
        max_element = max(masked)
        M = max_element if max_element != 0 else 0
    else:
