                    elif s == 2:
                        if not best_s2:
                            continue
                        sum_d = best_s2[0] + best_s2[1]
                        if x == 0:
                            damage = sum_d
                        elif x == 1:
                            damage = best_s2[0] * 2 + best_s2[1]
                        elif x == 2:
                            damage = best_s2[0] + best_s2[1] * 2
                        else:
