            v = int(input[ptr + 1])
            adj[u].append(v)
            adj[v].append(u)
            ptr += 2
        m = int(input[ptr])
        ptr += 1
        primes = list(map(int, input[ptr:ptr + m]))
        ptr += m

        # Compute a_b for each edge
        parent = [0] * (n + 1)
        size = [1] * (n + 1)
        root = 1
        stack = [(root, 0, False)]
        while stack:
            u, p, visited = stack.pop()
            if not visited:
                parent[u] = p
                stack.append((u, p, True))
                for v in adj[u]:
                    if v != p:
                        stack.append((v, u, False))
            else:
                for v in adj[u]:
                    if v != p:
                        size[u] += size[v]

        a_b = []
        for _ in range(n - 1):
            u, v = map(int, input[ptr:ptr+2])
            ptr +=2
            if parent[v] == u:
                a = size[v]
            elif parent[u] == v:
                a = size[u]
            else:
                assert False, "Invalid edge"
            b = n - a
            a_b.append(a * b)

        a_b.sort(reverse=True)
        primes.sort(reverse=True)
        labels = []
        if len(primes) >= len(a_b):
            for i in range(len(a_b)):
                labels.append(primes[i])
            remaining = primes[len(a_b):]
            for i in range(len(remaining)):
                labels[i] *= remaining[i]
        else:
            for i in range(len(primes)):
                labels.append(primes[i])
            for i in range(len(a_b) - len(primes)):
                labels.append(1)

        total = 0
        for ab, lbl in zip(a_b, labels):
            total = (total + ab * lbl) % MOD
        print(total % MOD)

