def main():
    sys.setrecursionlimit(1 << 25)
    H, W, K = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(H):
        grid.append(sys.stdin.readline().strip())

    # Precompute prefix sums for efficient sum queries
    prefix = [[0]*(W+1) for _ in range(H+1)]
    for i in range(1, H+1):
        row_sum = 0
        for j in range(1, W+1):
            row_sum += 1 if grid[i-1][j-1] == '1' else 0
            prefix[i][j] = prefix[i][j-1] + row_sum

    @lru_cache(maxsize=None)
    def get_sum(i1, i2, j1, j2):
        return prefix[i2][j2] - prefix[i1-1][j2] - prefix[i2][j1-1] + prefix[i1-1][j1-1]

    @lru_cache(maxsize=None)
    def min_cuts(i1, i2, j1, j2):
        total = get_sum(i1, i2, j1, j2)
        if total <= K:
            return 0

        min_cuts_val = float('inf')

        # Try vertical splits
        for j in range(j1, j2):
            left = get_sum(i1, i2, j1, j+1)
            right = get_sum(i1, i2, j+1, j2)
            if left <= K and right <= K:
                cuts = 1 + min_cuts(i1, i2, j1, j+1) + min_cuts(i1, i2, j+1, j2)
                if cuts < min_cuts_val:
                    min_cuts_val = cuts

        # Try horizontal splits
        for i in range(i1, i2):
            top = get_sum(i1, i, j1, j2)
            bottom = get_sum(i+1, i2, j1, j2)
            if top <= K and bottom <= K:
                cuts = 1 + min_cuts(i1, i, j1, j2) + min_cuts(i+1, i2, j1, j2)
                if cuts < min_cuts_val:
                    min_cuts_val = cuts

        return min_cuts_val

    print(min_cuts(1, H, 1, W))

if __name__ == "__main__":
    main()
