def generate_lucky_numbers(n):
    lucky = []
    max_digits = len(str(n)) if n > 0 else 0
    for length in range(1, 10):
        for digits in product('47', repeat=length):
            num_str = ''.join(digits)
            if len(num_str) > max_digits:
                continue
            num = int(num_str)
            if num <= n:
                lucky.append(num)
    return sorted(lucky)

def generate_kth_permutation(S, k):
    m = len(S)
    perm = []
    remaining = list(S)
    current_k = k - 1  # Convert to 0-based index
    for i in range(m):
        factorial = 1
        for j in range(1, m - i):
            factorial *= j
        index = current_k // factorial
        perm.append(remaining.pop(index))
        current_k %= factorial
    return perm

def main():
    n, k = map(int, sys.stdin.readline().split())

    # Check if permutation exists
    if n < 20:
        total = 1
        for i in range(1, n + 1):
            total *= i
            if total > k:
                break
        if k > total:
            print(-1)
            return

    # Generate all lucky numbers up to n
    lucky_numbers = generate_lucky_numbers(n)
    lucky_set = set(lucky_numbers)

    # Compute m (smallest integer where m! >= k)
    m = 1
    current_fact = 1
    while current_fact < k:
        m += 1
        current_fact *= m

    # Generate the permuted part's permutation
    start = n - m + 1
    if start < 1:
        start = 1
    S = list(range(start, n + 1))
    perm = generate_kth_permutation(S, k)

    # Calculate the count
    count = 0
    for i in lucky_numbers:
        if i <= (n - m):
            count += 1
        else:
            pos_in_perm = i - start
            if pos_in_perm < len(perm) and perm[pos_in_perm] in lucky_set:
                count += 1
