        best_s3 = []
        c1_list = [d for c, d in cards if c == 1]
        if len(c1_list) >= 3:
            best_s3 = sorted(c1_list, reverse=True)[:3]

        dp_new = [-10**18] * 10
        for m_prev in range(10):
            if dp_prev[m_prev] == -10**18:
