        for _ in range(n - 1):
            u, v = map(int, input[ptr:ptr+2])
            ptr +=2
            if parent[v] == u:
                a = size[v]
            elif parent[u] == v:
                a = size[u]
            else:
                assert False, "Invalid edge"
            b = n - a
            a_b.append(a * b)

        a_b.sort(reverse=True)
        primes.sort(reverse=True)
        labels = []
        if len(primes) >= len(a_b):
            for i in range(len(a_b)):
                labels.append(primes[i])
            remaining = primes[len(a_b):]
            for i in range(len(remaining)):
                labels[i] *= remaining[i]
        else:
